import{_ as t,o as e,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Get That Cluster Back Online, but Hurry Slowly - Gregory Orange, Pawsey Supercomputing Centre","description":"","frontmatter":{"title":"Get That Cluster Back Online, but Hurry Slowly - Gregory Orange, Pawsey Supercomputing Centre","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","Distributed Storage","Cluster Management","Fault Recovery","System Optimization"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Get_That_Cluster_Back_Online_but_Hurry_Slowly_-_Gregory_Orange_Pawsey_Supercomputing_Centre.md","filePath":"posts/2025/Get_That_Cluster_Back_Online_but_Hurry_Slowly_-_Gregory_Orange_Pawsey_Supercomputing_Centre.md","lastUpdated":1780459816000}'),a={name:"posts/2025/Get_That_Cluster_Back_Online_but_Hurry_Slowly_-_Gregory_Orange_Pawsey_Supercomputing_Centre.md"};function n(o,l,s,u,_,g){return e(),r("div",null,[...l[0]||(l[0]=[i('<h3 id="会议纪要-ceph集群故障处理与经验总结" tabindex="-1">会议纪要：Ceph集群故障处理与经验总结 <a class="header-anchor" href="#会议纪要-ceph集群故障处理与经验总结" aria-label="Permalink to &quot;会议纪要：Ceph集群故障处理与经验总结&quot;">​</a></h3><p><strong>会议主题</strong>：Ceph集群故障处理与经验分享<br><strong>主讲人</strong>：Greg (Pawsey Supercomputing Centre)<br><strong>会议时间</strong>：2023年<br><strong>参会人员</strong>：Ceph社区成员及相关技术专家</p><h4 id="_1-背景介绍" tabindex="-1">1. <strong>背景介绍</strong> <a class="header-anchor" href="#_1-背景介绍" aria-label="Permalink to &quot;1. **背景介绍**&quot;">​</a></h4><ul><li>Pawsey Supercomputing Centre是澳大利亚的两级高性能计算中心之一，专注于为科学研究提供计算服务。</li><li>该中心近年来转向使用Ceph对象存储系统，特别是为天文数据设计的高弹性集群ACAA Inest。</li><li>ACAA Inest集群在初期表现良好，但随着时间推移，由于节点故障和PG（Placement Group）分布不均等问题，集群健康状况恶化。</li></ul><h4 id="_2-故障发生与处理过程" tabindex="-1">2. <strong>故障发生与处理过程</strong> <a class="header-anchor" href="#_2-故障发生与处理过程" aria-label="Permalink to &quot;2. **故障发生与处理过程**&quot;">​</a></h4><ul><li><strong>故障背景</strong>： <ul><li>集群技术本身没有问题，但节点故障和PG分布不均导致集群健康状态不佳。</li><li>一次电力故障后，集群服务完全中断，尽管硬件故障未导致数据丢失，但恢复过程揭示了集群的不平衡问题。</li></ul></li><li><strong>故障表现</strong>： <ul><li>RGW（RADOS Gateway）频繁冻结，重启后仅能短暂恢复服务。</li><li>内存耗尽，尽管增加了内存分配，问题仍未解决。</li><li>垃圾回收（Garbage Collection）积压，堆积了数百万条未处理记录。</li><li>PG不一致，部分PG长时间无法修复，导致监控数据库无法自动修剪。</li></ul></li><li><strong>处理措施</strong>： <ul><li>使用upmap工具手动干预，重新平衡集群，优先处理降级的对象。</li><li>逐个重启OSD守护进程，最终发现一个卡住的OSD是导致问题的关键。</li><li>手动删除部分积压的垃圾回收记录，逐步恢复RGW的正常运行。</li></ul></li></ul><h4 id="_3-经验教训与改进措施" tabindex="-1">3. <strong>经验教训与改进措施</strong> <a class="header-anchor" href="#_3-经验教训与改进措施" aria-label="Permalink to &quot;3. **经验教训与改进措施**&quot;">​</a></h4><ul><li><strong>问题诊断</strong>： <ul><li>故障可能由多个因素共同导致，不应过度专注于单一症状。</li><li>在远程工作环境中，确保沟通清晰，避免误解。</li></ul></li><li><strong>团队协作</strong>： <ul><li>团队成员应定期交流，避免因疲劳或误解导致问题处理效率下降。</li><li>鼓励团队成员在长时间工作后适当休息，保持工作质量。</li></ul></li><li><strong>技术优化</strong>： <ul><li>upmap工具在处理集群不平衡时非常有效。</li><li>定期监控和记录集群的典型状态，以便快速识别异常。</li></ul></li><li><strong>外部支持</strong>： <ul><li>在问题复杂时，寻求外部专家的帮助可以提供新的视角和解决方案。</li></ul></li></ul><h4 id="_4-后续行动计划" tabindex="-1">4. <strong>后续行动计划</strong> <a class="header-anchor" href="#_4-后续行动计划" aria-label="Permalink to &quot;4. **后续行动计划**&quot;">​</a></h4><ul><li><strong>持续监控</strong>： <ul><li>加强对集群的监控，特别是PG分布、垃圾回收队列和监控数据库的自动修剪情况。</li></ul></li><li><strong>自动化工具</strong>： <ul><li>探索更高效的自动化工具，减少手动干预的需求。</li></ul></li><li><strong>团队培训</strong>： <ul><li>加强团队成员对Ceph集群管理的培训，特别是对upmap等高级工具的使用。</li></ul></li><li><strong>硬件维护</strong>： <ul><li>定期检查硬件状态，避免因硬件故障导致的集群不平衡。</li></ul></li></ul><h4 id="_5-问答环节" tabindex="-1">5. <strong>问答环节</strong> <a class="header-anchor" href="#_5-问答环节" aria-label="Permalink to &quot;5. **问答环节**&quot;">​</a></h4><ul><li><strong>Q1</strong>：是否有监控OSD延迟的系统？ <ul><li>在故障后开始监控，之前未特别关注。</li></ul></li><li><strong>Q2</strong>：是否有明确的故障原因？ <ul><li>故障由多个因素导致，最终发现一个卡住的OSD是关键，但未找到具体原因。</li></ul></li><li><strong>Q3</strong>：是否有计划改进日志分析系统？ <ul><li>正在逐步改进，计划通过快照和可视化工具更好地分析集群行为。</li></ul></li><li><strong>Q4</strong>：Ceph版本是否与问题有关？ <ul><li>使用的是Quincy版本，未明确发现版本问题，但可能存在OSD代码中的潜在bug。</li></ul></li></ul><p><strong>总结</strong>：本次会议详细分享了Pawsey Supercomputing Centre在处理Ceph集群故障中的经验与教训，强调了upmap工具在集群平衡中的重要性，并提出了未来的改进方向。通过团队协作、技术优化和外部支持，成功恢复了集群服务，并为未来的问题处理提供了宝贵的经验。</p>',13)])])}const c=t(a,[["render",n]]);export{h as __pageData,c as default};
